}

function is_undulating(n){
    if (n.toString().length < 3) return false; // A number with less than 3 digits cannot be undulating

    let isIncreasing = true;
    let isDecreasing = true;

    for (let i = 0; i < n.toString().length - 1; i++) {
        if (n.toString()[i] > n.toString()[i + 1]) {
            isIncreasing = false;
        }
        if (n.toString()[i] < n.toString()[i + 1]) {
            isDecreasing = false;
        }
    }

    return isIncreasing || isDecreasing;
}

function find_Rotations(str){
  let rotations = 0;
  let original = str;
  while (rotations < str.length) {
    str = str + str[0]; // Rotate the string by appending the first character to the end
    rotations++;
    if (str === original) { // If the rotated string matches the original, we found the minimum rotations
      return rotations;
    }
  }
  return rotations; // In case the string cannot be rotated to match itself, return the length of the string
}

function find_Rotations(str){
  if(str.length <= 1) return 0;

  let rotations = 0;
  let originalStr = str;

  while(rotations < originalStr.length){
    str = str.substring(1) + str.charAt(0);
    rotations++;

    if(str === originalStr) break;
  }

  return rotations;
}

function find_kth(arr1, arr2, k){
  let i = 0, j = 0;

  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] < arr2[j]) {
      i++;
    } else {
      j++;
    }
    k--;
    if (k === 0) {
      return arr1[i - 1];
    }
  }

  while (i < arr1.length) {
    k--;
    if (k === 0) {
      return arr1[i];
    }
    i++;
  }

  while (j < arr2.length) {
    k--;
    if (k === 0) {
      return arr2[j];
    }
    j++;
  }

  throw new Error('k is out of bounds');
}

