function max_sub_array_sum_repeated(a, n, k) {
    let max_sum = -Infinity;
    let current_sum = 0;

    // Find the maximum subarray sum in the original array
    for (let i = 0; i < n; i++) {
        current_sum += a[i];
        max_sum = Math.max(max_sum, current_sum);
    }

    // Find the maximum subarray sum in the repeated array
    for (let i = 0; i < n; i++) {
        current_sum += a[i];
        max_sum = Math.max(max_sum, current_sum);
    }

    // Find the maximum subarray sum in the repeated array after doubling the original array
    for (let i = 0; i < 2 * n; i++) {
        current_sum += a[i];
        max_sum = Math.max(max_sum, current_sum);
    }

    return max_sum;
}

function max_sub_array_sum_repeated(a, n, k) {
    let maxSum = 0;
    let currentSum = 0;
    let maxEnd = 0;
    let maxStart = 0;
    let end = 0;
    let start = 0;

    for(let i = 0; i < n * k; i++) {
        currentSum += a[i % n];
        if(currentSum > maxSum) {
            maxSum = currentSum;
            maxEnd = i;
        }
        if(currentSum < 0) {
            currentSum = 0;
            start = i + 1;
        }
    }

    for(let i = maxStart; i <= maxEnd; i++) {
        end = i;
        while(end < maxEnd && a[end] == a[maxEnd]) {
            end++;
        }
        maxSum = Math.max(maxSum, currentSum);
        currentSum = 0;
        start = end;
    }

    return maxSum;
}

