    const shiftedVowels = 'cdefghijklmnopqrstvwxyzCDEFGHIJKLMNOPQRSTUVWXYZ';
    let encodedMessage = '';

    for (let char of message) {
        if (vowels.includes(char)) {
            let index = vowels.indexOf(char);
            let shiftedIndex = (index + 2) % vowels.length;
            encodedMessage += shiftedVowels[shiftedIndex];
        } else {
