  // Iterate over the digits of both numbers
  for (let i = 0; i < Math.max(str1.length, str2.length); i++) {
    // Get the digit at the current position from both numbers
    const digit1 = str1[i] ? parseInt(str1[i]) : 0;
    const digit2 = str2[i] ? parseInt(str2[i]) : 0;

    // Calculate the absolute difference between the digits
    const diff = Math.abs(digit1 - digit2);

    // Add the difference to the sum
    sum += diff;
  }

  // Return the total sum of the per-digit differences
  return sum;
}

