    // Check if all rows, columns, and diagonals have the same sum
    for (let i = 0; i < 3; i++) {
        let rowSum = 0;
        let colSum = 0;
        let diagSum1 = 0;
        let diagSum2 = 0;

        // Row sum
        for (let j = 0; j < 3; j++) {
