        }

        // Column sum
        for (let j = 0; j < 3; j++) {
            colSum += my_matrix[j][i];
        }

        // Diagonal sum 1
        diagSum1 += my_matrix[i][i];

        // Diagonal sum 2
        diagSum2 += my_matrix[i][2 - i];

