function heap_sort(iterable){
  // Convert the iterable to an array
  const arr = Array.from(iterable);

  // Transform the array into a heap
  build_max_heap(arr);

  // Sort the array using the heap
  let end = arr.length - 1;
  while (end > 0) {
    // Swap the root (max element) with the last element
    [arr[0], arr[end]] = [arr[end], arr[0]];

    // Reduce the heap size by one
    end--;

    // Restore the heap property
    heapify(arr, 0, end);
  }

  // Return the sorted array
  return arr;
}

function build_max_heap(arr) {
  const n = arr.length;

  // Start from the last non-leaf node and move towards the root
  for (let i = Math.floor((n - 2) / 2); i >= 0; i--) {
    heapify(arr, i, n - 1);
  }
}

function heapify(arr, i, n) {
  let largest = i; // Initialize largest as root
  let left = 2 * i + 1; // Left child
  let right = 2 * i + 2; // Right child

  // If left child is larger than root
  if (left < n && arr[left] > arr[largest]) {
    largest = left;
  }

  // If right child is larger than largest so far
  if (right < n && arr[right] > arr[largest]) {
    largest = right;
  }

  // If largest is not root
  if (largest !== i) {
    [arr[i], arr[largest]] = [arr[largest], arr[i]];

    // Recursively heapify the affected sub-tree
    heapify(arr, largest, n);
  }
}

