function histogram(test) {
  const letterCounts = {};
  let maxCount = 0;
  let mostFrequentLetters = [];

  for (const letter of test.split(' ')) {
    if (letterCounts[letter]) {
      letterCounts[letter]++;
    } else {
      letterCounts[letter] = 1;
    }

    if (letterCounts[letter] > maxCount) {
      maxCount = letterCounts[letter];
      mostFrequentLetters = [letter];
    } else if (letterCounts[letter] === maxCount) {
      mostFrequentLetters.push(letter);
    }
  }

  return mostFrequentLetters.reduce((acc, letter) => ({ ...acc, [letter]: letterCounts[letter] }), {});
}

function histogram(test) {
  if (test === "") return {};

  const testArray = test.split(" ");
  const letterCount = {};

  testArray.forEach(letter => {
    if (letterCount[letter]) {
      letterCount[letter]++;
    } else {
      letterCount[letter] = 1;
    }
  });

  let maxCount = 0;
  const maxLetters = [];

  for (const letter in letterCount) {
    if (letterCount[letter] > maxCount) {
      maxCount = letterCount[letter];
      maxLetters = [letter];
    } else if (letterCount[letter] === maxCount) {
      maxLetters.push(letter);
    }
  }

  return Object.fromEntries(maxLetters.map(letter => [letter, letterCount[letter]]));
}

